48	const PROCESSING_FEE = 5;
49	const FIRST_INSURANCE_SURCHARGE = 0.1;
50	
51	const BASE_PREMIUMS: Record<string, number> = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	};
57	
58	const quotePremium = (items: Item[]): number => {
59	  const policyBasePremium = items.reduce(
60	    (sum, item) => sum + BASE_PREMIUMS[item.type],
61	    0,
62	  );
63	  return (
64	    policyBasePremium +
65	    policyBasePremium * FIRST_INSURANCE_SURCHARGE +
66	    PROCESSING_FEE
67	  );
68	};
69	
70	const runStep = (step: Step): StepResult => ({
71	  premium: quotePremium((step as QuoteStep).items),
72	});
73	
74	export const runScenario = (scenario: Scenario): ScenarioResult => ({
75	  results: scenario.steps.map(runStep),
76	});
